parameters.jsCode:
const ctx = $('Prepare Context P2').first().json;
const SERPER_KEY = $env.SERPER_API_KEY;

var clientData = {};
try {
  clientData = typeof ctx.client_data === 'string' 
    ? JSON.parse(ctx.client_data) 
    : (ctx.client_data || {});
} catch(e) {
  clientData = {};
}

const clientNom = ctx.client_nom || '';
const secteur = ctx.secteur || '';
const localisation = ctx.localisation || '';

async function search(context, query) {
  try {
    var data = await context.helpers.httpRequest({
      method: 'POST',
      url: 'https://google.serper.dev/search',
      headers: { 'X-API-KEY': SERPER_KEY, 'Content-Type': 'application/json' },
      body: JSON.stringify({ q: query, gl: 'fr', hl: 'fr', num: 5 }),
    });
    var results = data.organic || [];
    return results.slice(0, 5).map(function(r) { 
      return '- ' + r.title + ': ' + r.snippet; 
    }).join('\n');
  } catch (e) {
    return 'Aucun resultat';
  }
}

var r1a = await search(this, secteur + ' taille marche France 2025 2026 chiffres');
var r1b = await search(this, secteur + ' croissance marche tendances previsions');
var r2a = await search(this, secteur + ' principaux acteurs leaders France');
var r2b = await search(this, secteur + ' startups emergentes nouveaux entrants');
var r3a = await search(this, secteur + ' chaine de valeur fournisseurs distributeurs');
var r3b = await search(this, secteur + ' ecosysteme partenaires dependances');
var r4a = await search(this, secteur + ' reglementation lois normes France 2025 2026');
var r4b = await search(this, secteur + ' RGPD conformite certification obligations');
var r5a = await search(this, clientNom + ' concurrents directs comparatif');
var r5b = await search(this, clientNom + ' parts de marche positionnement prix');
var r6a = await search(this, secteur + ' profil clients segmentation marche B2B B2C');
var r6b = await search(this, secteur + ' comportement achat tendances consommation');

var prompt = 'Tu es un analyste sectoriel senior dans un cabinet de conseil strategy. '
  + 'Tu produis une etude sectorielle complete et structuree au format JSON strict. '
  + 'Reponds UNIQUEMENT avec le JSON, sans backticks, sans texte avant ou apres.\n\n';

prompt += '## CLIENT\n'
  + 'Nom: ' + clientNom + '\n'
  + 'Secteur: ' + secteur + '\n'
  + 'Localisation: ' + localisation + '\n\n';

if (clientData.synthese_consultant) {
  prompt += '## SYNTHESE PHASE 1 (contexte)\n' + clientData.synthese_consultant + '\n\n';
}
if (clientData.positionnement) {
  prompt += '## POSITIONNEMENT CLIENT (Phase 1)\n'
    + 'Activite: ' + (clientData.positionnement.activite_principale || '') + '\n'
    + 'Clients types: ' + (clientData.positionnement.clients_types || '') + '\n'
    + 'Zone: ' + (clientData.positionnement.zone_geographique || '') + '\n\n';
}

prompt += '## 2.1 VOLUME ET DYNAMIQUES DU MARCHE\n' + r1a + '\n' + r1b + '\n\n';
prompt += '## 2.2 CARTOGRAPHIE DES ACTEURS\n' + r2a + '\n' + r2b + '\n\n';
prompt += '## 2.3 CHAINE DE VALEUR ET INTERACTIONS\n' + r3a + '\n' + r3b + '\n\n';
prompt += '## 2.4 ENVIRONNEMENT NORMATIF\n' + r4a + '\n' + r4b + '\n\n';
prompt += '## 2.5 ANALYSE CONCURRENTIELLE\n' + r5a + '\n' + r5b + '\n\n';
prompt += '## 2.6 SEGMENT DE MARCHE ET CLIENTELE\n' + r6a + '\n' + r6b + '\n\n';

prompt += '## FORMAT JSON ATTENDU\n'
  + '{\n'
  + '  "volume_marche": {\n'
  + '    "taille_marche_france": "",\n'
  + '    "taille_marche_europe": "",\n'
  + '    "taux_croissance_annuel": "",\n'
  + '    "tendances_macro": [""],\n'
  + '    "facteurs_croissance": [""],\n'
  + '    "freins_identifies": [""]\n'
  + '  },\n'
  + '  "acteurs_cles": {\n'
  + '    "leaders": [{"nom": "", "description": "", "part_marche_estimee": ""}],\n'
  + '    "challengers": [{"nom": "", "description": ""}],\n'
  + '    "emergents": [{"nom": "", "description": ""}]\n'
  + '  },\n'
  + '  "chaine_valeur": {\n'
  + '    "description_chaine": "",\n'
  + '    "maillons_cles": [""],\n'
  + '    "dependances_critiques": [""],\n'
  + '    "points_vulnerabilite": [""]\n'
  + '  },\n'
  + '  "environnement_normatif": {\n'
  + '    "reglementations_en_vigueur": [{"nom": "", "impact": ""}],\n'
  + '    "reglementations_a_venir": [{"nom": "", "echeance": "", "impact": ""}],\n'
  + '    "certifications_requises": [""],\n'
  + '    "risques_conformite": [""]\n'
  + '  },\n'
  + '  "analyse_concurrentielle": {\n'
  + '    "concurrents_directs": [{"nom": "", "forces": "", "faiblesses": ""}],\n'
  + '    "positionnement_client": "",\n'
  + '    "avantages_concurrentiels_client": [""],\n'
  + '    "menaces": [""],\n'
  + '    "opportunites_differenciation": [""]\n'
  + '  },\n'
  + '  "segment_clientele": {\n'
  + '    "profil_client_type": "",\n'
  + '    "segmentation": [{"segment": "", "description": "", "poids_estime": ""}],\n'
  + '    "tendances_comportementales": [""],\n'
  + '    "besoins_non_couverts": [""]\n'
  + '  },\n'
  + '  "synthese_sectorielle": ""\n'
  + '}\n\n'
  + 'Remplis chaque champ avec les donnees trouvees. Si une information n est pas disponible, ecris Non trouve.';

var body = {
  model: 'claude-sonnet-4-6',
  max_tokens: 16000,
  temperature: 0.2,
  messages: [{ role: 'user', content: prompt }]
};

return [{
  json: {
    api_body: JSON.stringify(body),
    mission_id: ctx.mission_id,
    client_id: ctx.client_id,
    client_nom: clientNom,
    nom_mission: ctx.nom_mission,
    callback_url: ctx.callback_url,
    prospect_id: ctx.prospect_id,
  }
}];

const response = $input.first().json;
const raw = response.content?.[0]?.text || '';
const usage = response.usage || {};
const prev = $('Recherches sectorielles').first().json;

var cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
var start = cleaned.indexOf('{');
var end = cleaned.lastIndexOf('}');
if (start !== -1 && end !== -1 && end > start) {
  cleaned = cleaned.slice(start, end + 1);
}

var result = {
  mission_id: prev.mission_id,
  client_id: prev.client_id,
  client_nom: prev.client_nom,
  nom_mission: prev.nom_mission,
  callback_url: prev.callback_url,
  prospect_id: prev.prospect_id,
  tokens_input: usage.input_tokens || 0,
  tokens_output: usage.output_tokens || 0,
  parse_success: false,
  analyse_data: null,
  analyse_json_string: null,
  raw_response: raw
};

try {
  var analyse = JSON.parse(cleaned);
  var jsonString = JSON.stringify(analyse).replace(/'/g, "''");
  result.parse_success = true;
  result.analyse_data = analyse;
  result.analyse_json_string = jsonString;
} catch (e) {
  result.parse_error = e.message;
}

return [{ json: result }];

